/* @lc app=leetcode id=3551 lang=kotlin */ class Solution { fun minSwaps(nums: IntArray): Int = nums.indices.map { i -> Triple(nums[i], i, nums[i].toString().sumOf { it - '0' }) }.sortedWith(compareBy({ it.third }, { it.first })).let { sorted -> BooleanArray(nums.size).let { vis -> nums.indices.sumOf { i -> if (vis[i]) 0 else generateSequence(i) { j -> sorted[j].second.takeIf { !vis[it] } }.onEach { j -> vis[j] = true }.count().let { maxOf(0, it - 1) } } } } }